14	// Sync brings one repository up to date with its upstream (§3.17).
15	//
16	// It is the counterpart of Clone: the explorer creates what is missing, this
17	// reconciles what exists. Four rules shape it, and all but the third are a
18	// refusal rather than a cleverness.
19	//
20	//  1. **It fetches first, always, whatever the working tree looks like.** The
21	//     "unpulled" count DevDesk shows comes from `@{u}`, the *local*
22	//     remote-tracking ref, which nothing moved until now — so it read 0 on a
23	//     repository forty commits behind (D35). A sync that decided from that
24	//     number would be reconciling against an answer it had not checked.
25	//
26	//  2. **It only fast-forwards.** No merge commit, no rebase, no stash. A
27	//     divergence is a decision about someone's unpublished work, and a tool
28	//     that guesses at it can destroy hours in a keystroke the user cannot undo.
29	//
30	//  3. **Tags follow the remote, forced.** A tag rewritten upstream either
31	//     stays stale here without a word (a plain fetch never updates a tag it
32	//     already has) or fails the whole fetch with "would clobber existing tag"
33	//     when the repository asks for every tag (`tagOpt = --tags`). Both left the
34	//     branch unsynced or wrong, so the tags are fetched first, forced, and
35	//     every one that moved is named in MovedTags: a tag has no reflog, and its
36	//     old target is otherwise gone without a trace.
37	//
38	//  4. **It never pushes.** Sync is the pull direction. Publishing is a separate
39	//     intent with separate failure modes, and nothing about "reconcile what
40	//     exists" implies it.
41	//
42	// A repository it declines is still better off than before: the fetch happened,
43	// so its counts are true and the row finally says how far behind it really is.
44	func Sync(repoPath string, opts SyncOptions) (SyncResult, error) {
45		// Tags before branches: once the tags agree with the remote, a
46		// repository configured with `tagOpt = --tags` has nothing left for its
47		// own fetch to refuse.
48		moved, err := syncTags(repoPath, opts.Token)
49		if err != nil {
50			return SyncResult{}, err
51		}
52		// --prune drops remote-tracking branches the remote deleted; --no-prune-tags
53		// keeps fetch.pruneTags from extending that to local tags (see syncTags).
54		if _, err := run(repoPath, opts.Token, "fetch", "--quiet", "--prune", "--no-prune-tags"); err != nil {
55			return SyncResult{}, err
56		}
57		result, err := reconcile(repoPath)
58		result.MovedTags = moved
59		return result, err
60	}
