62	// reconcile decides, once everything is fetched, whether the branch can move.
63	func reconcile(repoPath string) (SyncResult, error) {
64	
65		// Order matters below: a repository can be several of these at once, and
66		// the first answer is the one that explains why nothing moved.
67		if _, err := run(repoPath, "", "symbolic-ref", "--quiet", "HEAD"); err != nil {
68			return skipped("detached HEAD"), nil
69		}
70		upstream, err := run(repoPath, "", "rev-parse", "--abbrev-ref", "--symbolic-full-name", "@{u}")
71		if err != nil {
72			return skipped("no upstream branch"), nil
73		}
74	
75		behind, ahead, err := divergence(repoPath)
76		if err != nil {
77			return SyncResult{}, err
78		}
79	
80		result := SyncResult{Behind: behind, Ahead: ahead, Upstream: strings.TrimSpace(upstream)}
81	
82		// Nothing to pull. Local commits waiting to be pushed do not change that:
83		// sync is the pull direction, and rule 3 leaves them alone.
84		if behind == 0 {
85			result.Outcome = SyncUpToDate
86			return result, nil
87		}
88		if ahead > 0 {
89			result.Outcome = SyncSkipped
90			result.Reason = fmt.Sprintf("diverged — %s ahead", plural(ahead, "commit"))
91			return result, nil
92		}
93		if dirty, err := isDirty(repoPath); err != nil {
94			return SyncResult{}, err
95		} else if dirty {
96			result.Outcome = SyncSkipped
97			result.Reason = "uncommitted changes"
98			return result, nil
99		}
100	
101		if _, err := run(repoPath, "", "merge", "--ff-only", "--quiet", "@{u}"); err != nil {
102			return SyncResult{}, err
103		}
104		result.Outcome = SyncUpdated
105		return result, nil
106	}
