108	// RemoteURL returns a repository's `origin` URL, in whatever form it is stored.
109	//
110	// The caller needs it to decide which credential, if any, may be offered to
111	// this repository — a question this package deliberately does not answer.
112	func RemoteURL(repoPath string) (string, error) {
113		out, err := run(repoPath, "", "remote", "get-url", "origin")
114		if err != nil {
115			return "", err
116		}
117		return strings.TrimSpace(out), nil
118	}
