120	// SyncOptions is what a sync needs beyond the path.
121	type SyncOptions struct {
122		// Token authenticates the fetch over HTTPS. It must be a credential for the
123		// repository's own remote host: the caller decides, because this package
124		// cannot know which forge a working copy on disk came from. Empty means the
125		// fetch is expected to succeed without one.
126		Token string
127	}
128	
129	// SyncOutcome is what a sync did to one repository.
130	type SyncOutcome int
131	
132	const (
133		// SyncUpToDate: the fetch found nothing to pull.
134		SyncUpToDate SyncOutcome = iota
135		// SyncUpdated: the branch was fast-forwarded.
136		SyncUpdated
137		// SyncSkipped: fetched, but not merged. Reason says why, and it is never a
138		// failure — the repository is in the state its owner left it in.
139		SyncSkipped
140	)
141	
142	// SyncResult is what one repository's sync established.
143	type SyncResult struct {
144		Outcome SyncOutcome
145		// Behind and Ahead are counted after the fetch, so unlike the workspaces
146		// listing's own columns they are current.
147		Behind   int
148		Ahead    int
149		Upstream string
150		Reason   string
151		// MovedTags names the local tags the remote rewrote and the sync moved to
152		// follow it, sorted. It is filled whatever the outcome — a skipped or
153		// up-to-date repository has had its tags fetched all the same.
154		MovedTags []string
155	}
156	
157	func skipped(reason string) SyncResult {
158		return SyncResult{Outcome: SyncSkipped, Reason: reason}
159	}
