161	// syncTags force-fetches every tag from the remote the current branch pulls
162	// from, and returns the local tags that now point somewhere else.
163	//
164	// It never prunes: `--prune` with a tag refspec deletes every tag the remote
165	// does not have, which is a tag someone made here and never pushed. That is
166	// also what a global `fetch.prune = true` does to this refspec, so the flag is
167	// passed explicitly rather than assumed absent.
168	//
169	// The branch fetch in Sync prunes, and `fetch.pruneTags = true` (or
170	// `remote.<name>.pruneTags`) would make that prune cover refs/tags/* too,
171	// deleting the same local-only tags this function keeps. Sync therefore passes
172	// `--no-prune-tags` there (git 2.17+, DEVDESK-135).
173	//
174	// A repository with no such remote — a local-only one, or a branch tracking
175	// "." — has no tags to follow, and that is not an error: the branch fetch
176	// after it decides what the repository's remotes allow.
177	func syncTags(repoPath, token string) ([]string, error) {
178		remote := tagRemote(repoPath)
179		if remote == "" {
180			return nil, nil
181		}
182		before, err := tagTargets(repoPath)
183		if err != nil {
184			return nil, err
185		}
186		if _, err := run(repoPath, token, "fetch", "--quiet", "--no-tags", "--no-prune", remote, "+refs/tags/*:refs/tags/*"); err != nil {
187			return nil, err
188		}
189		after, err := tagTargets(repoPath)
190		if err != nil {
191			return nil, err
192		}
193		var moved []string
194		for name, old := range before {
195			if target, ok := after[name]; ok && target != old {
196				moved = append(moved, name)
197			}
198		}
199		sort.Strings(moved)
200		return moved, nil
201	}
202	
203	// tagRemote is the remote a plain `git fetch` would use: the current branch's
204	// own, or `origin`. Empty when that remote does not exist.
205	func tagRemote(repoPath string) string {
206		remote := "origin"
207		if branch, err := run(repoPath, "", "symbolic-ref", "--quiet", "--short", "HEAD"); err == nil {
208			if name, err := run(repoPath, "", "config", "--get", "branch."+strings.TrimSpace(branch)+".remote"); err == nil {
209				remote = strings.TrimSpace(name)
210			}
211		}
212		out, err := run(repoPath, "", "remote")
213		if err != nil {
214			return ""
215		}
216		for _, name := range strings.Fields(out) {
217			if name == remote {
218				return remote
219			}
220		}
221		return ""
222	}
223	
224	// tagTargets maps each local tag to the object it names — the tag object for
225	// an annotated tag, so re-annotating one on the same commit counts as a move.
226	func tagTargets(repoPath string) (map[string]string, error) {
227		out, err := run(repoPath, "", "for-each-ref", "--format=%(refname:strip=2) %(objectname)", "refs/tags")
228		if err != nil {
229			return nil, err
230		}
231		targets := make(map[string]string)
232		for _, line := range strings.Split(out, "\n") {
233			if name, target, ok := strings.Cut(strings.TrimSpace(line), " "); ok {
234				targets[name] = target
235			}
236		}
237		return targets, nil
238	}
239	
240	// divergence counts what separates HEAD from its upstream, in both directions.
241	func divergence(repoPath string) (behind, ahead int, err error) {
242		out, err := run(repoPath, "", "rev-list", "--count", "--left-right", "@{u}...HEAD")
243		if err != nil {
244			return 0, 0, err
245		}
246		fields := strings.Fields(out)
247		if len(fields) != 2 {
248			return 0, 0, fmt.Errorf("unreadable rev-list output: %q", strings.TrimSpace(out))
249		}
250		if behind, err = strconv.Atoi(fields[0]); err != nil {
251			return 0, 0, fmt.Errorf("unreadable behind count: %w", err)
252		}
253		if ahead, err = strconv.Atoi(fields[1]); err != nil {
254			return 0, 0, fmt.Errorf("unreadable ahead count: %w", err)
255		}
256		return behind, ahead, nil
257	}
258	
259	// isDirty reports whether the working tree has anything uncommitted, untracked
260	// files included: a fast-forward can refuse to overwrite one, and a refusal is
261	// better reported before the merge than as git's error after it.
262	func isDirty(repoPath string) (bool, error) {
263		out, err := run(repoPath, "", "status", "--porcelain")
264		if err != nil {
265			return false, err
266		}
267		return strings.TrimSpace(out) != "", nil
268	}
269	
270	// run executes one git command in a repository and returns its stdout.
271	//
272	// It carries the same non-interactive environment as Clone. A `git fetch` is a
273	// network call like any other, and left to itself it reaches the credential
274	// helper — which on Windows writes to the console over the rendered frame and
275	// then waits on a browser. That was §3.16's observed failure, and nothing about
276	// it was specific to cloning.
277	func run(repoPath, token string, args ...string) (string, error) {
278		return runContext(context.Background(), repoPath, token, args...)
279	}
280	
281	// runContext is run with a context, so a long fetch can be abandoned.
282	func runContext(ctx context.Context, repoPath, token string, args ...string) (string, error) {
283		return runContextMax(ctx, repoPath, token, 0, args...)
284	}
285	
286	// ErrOutputTooLarge is returned when a command wrote more than it was allowed.
287	var ErrOutputTooLarge = errors.New("output is larger than allowed")
288	
289	// capWriter collects output up to max bytes (no limit when max is 0) and fails
290	// the write past it, which makes the child's stdout copy fail and stops the
291	// process instead of buffering whatever it wants to say.
292	type capWriter struct {
293		buf      strings.Builder
294		max      int64
295		exceeded bool
296	}
297	
298	func (w *capWriter) Write(p []byte) (int, error) {
299		if w.max > 0 && int64(w.buf.Len()+len(p)) > w.max {
300			w.exceeded = true
301			return 0, ErrOutputTooLarge
302		}
303		return w.buf.Write(p)
304	}
305	
306	// hardening is the configuration a read-only command runs with, ahead of its
307	// own arguments: the repository is not trusted, and its .git/config or hooks
308	// must not make a read run a program of its choosing (DEVDESK-753). A -c option
309	// wins over every configuration file. /dev/null also works for git on Windows,
310	// which maps it itself.
311	//
312	// It stops the two hooks a status reaches without any user action, the file
313	// system monitor and the repository's hooks. Other settings that name a program
314	// (a filter driver, an external diff) are not covered.
315	//
316	// Only runReadOnly applies it. Sync, clone, fetch and pull go through
317	// runContextMax, which leaves the repository's hooks alone: a post-merge hook
318	// such as git-lfs's is part of what the user asked for when syncing.
319	func hardening() []string {
320		return []string{"-c", "core.fsmonitor=false", "-c", "core.hooksPath=" + os.DevNull}
321	}
322	
323	// runContextMax is runContext with a ceiling on what stdout may hold.
324	func runContextMax(ctx context.Context, repoPath, token string, max int64, args ...string) (string, error) {
325		return runGit(ctx, false, repoPath, token, max, args...)
326	}
327	
328	// runReadOnly runs a command that only reads a repository, with the hardening
329	// above and without taking the index lock: a status must not make a concurrent
330	// git of the user fail for no reason.
331	func runReadOnly(ctx context.Context, repoPath string, args ...string) (string, error) {
332		return runGit(ctx, true, repoPath, "", 0, args...)
333	}
334	
335	func runGit(ctx context.Context, readOnly bool, repoPath, token string, max int64, args ...string) (string, error) {
336		env := nonInteractiveEnv(token)
337		if readOnly {
338			args = append(hardening(), args...)
339			env = append(env, "GIT_OPTIONAL_LOCKS=0")
340		}
341		cmd := exec.CommandContext(ctx, "git", args...)
342		cmd.Dir = repoPath
343		cmd.Env = env
344	
345		stdout := &capWriter{max: max}
346		var stderr strings.Builder
347		cmd.Stdin = nil
348		cmd.Stdout = stdout
349		cmd.Stderr = &stderr
350	
351		if err := cmd.Run(); err != nil {
352			if ctx.Err() != nil {
353				return "", ctx.Err()
354			}
355			// The process may die of the broken pipe before Run reports the write
356			// error, so the flag is the reliable signal.
357			if stdout.exceeded {
358				return "", ErrOutputTooLarge
359			}
360			if reason := lastLine(stderr.String()); reason != "" {
361				return "", fmt.Errorf("%s", reason)
362			}
363			return "", err
364		}
365		return stdout.buf.String(), nil
366	}
367	
368	func plural(n int, word string) string {
369		if n == 1 {
370			return "1 " + word
371		}
372		return strconv.Itoa(n) + " " + word + "s"
373	}
